-- make_canonical v1 (run make_canonical_v1_20261026): one source of truth for makes, built on make_alias_ref.
-- Additive. Revert: see /workspace/v35/REVERT35.md (every data change is in make_reconcile_log with old values).
create table if not exists public.make_reconcile_log(
  id bigserial primary key, run_id text not null, table_name text not null, row_pk text not null,
  column_name text not null, old_value jsonb, new_value jsonb, reason text not null,
  created_at timestamptz not null default now());
create index if not exists make_reconcile_log_run_idx on public.make_reconcile_log(run_id);
create index if not exists make_alias_ref_alias_active_idx on public.make_alias_ref(alias_text) where retired_at is null;

-- 1. spaced / punctuation variants (kind case_punct, same_make), each cites a vehicle carrying that make text
insert into public.make_alias_ref(alias_text,canonical_make,kind,evidence_count,citation_url,citation_vehicle_id,rule,run_id,relation_type)
select x.alias_text,x.canonical_make,'case_punct',x.evidence_count,x.citation_url,x.citation_vehicle_id,
       'make_canonical_v1: make text equals canonical after removing spaces, hyphens and dots','make_canonical_v1_20261026','same_make'
