-- 2. make_canonical
create or replace function public.make_canonical(p_make text, p_year integer default null)
returns table(canonical_make text, relation_type text, comp_pool_make text, comp_pool_relation text, related_makes text[])
language plpgsql stable set search_path=public as $f$
declare m text; n text; hops int := 0; s text; er record;
begin
  m := nullif(lower(btrim(regexp_replace(coalesce(p_make,''),'\s+',' ','g'))),'');
  if m is null then return; end if;
  relation_type := 'identity';
  -- year-dependent meaning (canonical_make_era_rules); null canonical_make_id = do not map
  if p_year is not null then
    select r.canonical_make_id, c.canonical_name into er from canonical_make_era_rules r
      left join canonical_makes c on c.id = r.canonical_make_id
     where lower(r.make_text) = m and (r.year_min is null or p_year >= r.year_min) and (r.year_max is null or p_year <= r.year_max)
     order by r.id limit 1;
    if found then
      if er.canonical_make_id is not null then m := lower(er.canonical_name); end if;
      relation_type := 'era_rule'; hops := 3;  -- era rules are final for collapse
    end if;
  end if;
  loop
    exit when hops >= 3;
    n := null;
    select r.canonical_make into n from make_alias_ref r
     where r.alias_text=m and r.relation_type='same_make' and r.retired_at is null and r.canonical_make<>m
       -- a truncated_make row whose alias is itself a marque (austin, international) needs the model word: no collapse on make text alone
       and not (r.kind = 'truncated_make' and exists (select 1 from canonical_makes c where lower(c.canonical_name) = r.alias_text))
     order by r.evidence_count desc, r.id limit 1;
    exit when n is null;
    m := n; hops := hops+1; relation_type := 'same_make';
  end loop;
  select r.canonical_make into s from make_alias_ref r
   where r.alias_text=m and r.relation_type='successor_brand' and r.retired_at is null
   order by r.evidence_count desc, r.id limit 1;
  canonical_make := m; comp_pool_make := coalesce(s,m);
  comp_pool_relation := case when s is null then 'self' else 'successor_brand' end;
  select array_agg(distinct r.relation_type||':'||r.canonical_make) into related_makes from make_alias_ref r
   where r.alias_text=m and r.relation_type in ('tuner_or_builder','replica') and r.retired_at is null;
  return next;
end $f$;
comment on function public.make_canonical(text,integer) is 'make_canonical_v1: same_make rows collapse (<=3 hops); successor_brand only sets comp_pool_make (join flag); tuner_or_builder and replica never collapse (listed in related_makes).';
create or replace function public.make_canonical_key(p_make text, p_year integer default null) returns text language sql stable set search_path=public as
$f$ select canonical_make from public.make_canonical(p_make, p_year) $f$;
create or replace function public.make_comp_pool_key(p_make text, p_year integer default null) returns text language sql stable set search_path=public as
$f$ select comp_pool_make from public.make_canonical(p_make, p_year) $f$;

-- 3. Continental marque row (Continental Division of Ford, 1956-1958 make; Mark II 1956-57)
insert into public.canonical_makes(canonical_name,display_name,aliases,country_of_origin,founded_year,parent_company,is_active)
select 'CONTINENTAL','Continental','{}'::text[],'USA',1955,'Ford Motor Company',true
where not exists (select 1 from public.canonical_makes where canonical_name='CONTINENTAL');
insert into public.make_reconcile_log(run_id,table_name,row_pk,column_name,old_value,new_value,reason)
select 'make_canonical_v1_20261026','canonical_makes',id::text,'*row',null,to_jsonb(c),'new marque row: Continental Division (Mark II); vehicles had 187 null + 5 LINCOLN'
from public.canonical_makes c where canonical_name='CONTINENTAL';
insert into public.canonical_make_citations(canonical_make_id,make_text,claim,source_url,run_id)
select id,'Continental','The Continental Mark II was sold by the Continental Division of Ford for 1956-1957, as a successor to the Lincoln Continental.','https://en.wikipedia.org/wiki/Continental_Mark_II','make_canonical_v1_20261026'
from public.canonical_makes where canonical_name='CONTINENTAL';
insert into public.canonical_make_era_rules(make_text,year_min,year_max,canonical_make_id,rule,source_url,run_id)
select 'Continental',1955,1960,id,'make text Continental with model year 1955-1960 is the Continental marque (Mark II-V), not Lincoln','https://en.wikipedia.org/wiki/Continental_Mark_II','make_canonical_v1_20261026'
from public.canonical_makes where canonical_name='CONTINENTAL';
insert into public.make_reconcile_log(run_id,table_name,row_pk,column_name,old_value,new_value,reason)
select 'make_canonical_v1_20261026','canonical_make_era_rules',id::text,'*row',null,to_jsonb(r),'Continental 1955-1960 era rule'
from public.canonical_make_era_rules r where run_id='make_canonical_v1_20261026';

-- 4. link canonical_makes into make_alias_ref via make_canonical (nothing deleted; aliases untouched)
alter table public.canonical_makes add column if not exists make_ref_key text,
  add column if not exists make_ref_pool_key text, add column if not exists make_ref_relation text;
comment on column public.canonical_makes.make_ref_key is 'make_canonical(canonical_name).canonical_make: link into make_alias_ref (source of truth)';
with u as (
  update public.canonical_makes c set make_ref_key=m.canonical_make, make_ref_pool_key=m.comp_pool_make, make_ref_relation=m.comp_pool_relation
  from public.canonical_makes c0 cross join lateral public.make_canonical(c0.canonical_name) m
  where c0.id=c.id returning c.id, m.canonical_make, m.comp_pool_make, m.comp_pool_relation)
insert into public.make_reconcile_log(run_id,table_name,row_pk,column_name,old_value,new_value,reason)
select 'make_canonical_v1_20261026','canonical_makes',id::text,'make_ref_key,make_ref_pool_key,make_ref_relation',null,
       jsonb_build_array(canonical_make,comp_pool_make,comp_pool_relation),'link canonical_makes row to make_canonical' from u;
